  const KEY = 'murmur_app_backup_preview_v5'; // progress remains compatible across v0.5/v0.6
  const PREVIEW = window.MURMUR_APP_PREVIEW === true;
  const ARCHIVE = {"chapters": [{"name": "E1｜被選中的人", "range": "2020-09 ～ 2020-12", "tasks": [{"id": "diary", "label": "打開至少一篇日記，確認她如何開始認定自己被選中。", "hint": "可從 2020-11-12 01:47 或 2020-12-24 開始。"}, {"id": "notes", "label": "查看〈備忘錄 · 她〉。", "hint": "這是 E1 最後一則資料。"}]}, {"name": "E2｜室友", "range": "2021-01 ～ 2021-03", "tasks": [{"id": "notes", "label": "查看〈回覆紀錄〉或〈上線紀錄〉。", "hint": "她開始記錄回覆字數與上線時間。"}, {"id": "drafts", "label": "查看〈沒送出的訊息〉。", "hint": "這裡能看到她沒有傳出去的內容。"}]}, {"name": "E3｜04-10", "range": "2021-04-01 ～ 2021-04-12", "tasks": [{"id": "messages", "label": "比較 04-10 的兩份手機備份（v2 與 v1）。", "hint": "一份是她自己留下的版本，一份是原始版本。"}, {"id": "diary", "label": "再讀 2021-04-10 23:51 之後的日記。", "hint": "從這裡開始，稱呼規則會改變。"}]}, {"name": "童年插章｜舊部落格", "range": "2007 ～ 2010", "tasks": [{"id": "blog", "label": "閱讀舊部落格備份。", "hint": "至少讀到〈2007-05-11 下雨〉或〈2010-04-08〉。"}]}, {"name": "E4｜準備", "range": "2021-04-13 ～ 2021-04-22", "tasks": [{"id": "stories", "label": "查看〈小帳 · 限時動態觀看紀錄〉。", "hint": "觀看次數本身就是線索。"}, {"id": "searches", "label": "查看 04-20 搜尋紀錄。", "hint": "它對應 E4 後期的想法。"}, {"id": "drafts", "label": "查看〈草稿 · PLAN-7F3〉。", "hint": "主線已有，這裡補她寫下時的心情。"}]}, {"name": "E5｜那一晚", "range": "2021-04-23", "tasks": [{"id": "diary", "label": "閱讀 2021-04-23 20:41 的日記。", "hint": "那一晚開始前的記錄。"}, {"id": "drafts", "label": "閱讀 2021-04-23 的沒送出訊息。", "hint": "搭配〈最後一篇〉一起看。"}]}, {"name": "尾聲｜yoru 附註", "range": "END", "tasks": [{"id": "notes", "label": "閱讀 yoru 的附註。", "hint": "全部章節解開後才會出現。"}]}], "records": {"diary": [{"id": "diary_1", "heading": "日記 · 2020-09-14", "date": "2020-09-14", "title": "日記 · 2020-09-14", "chapter": 0, "body": "新公司\n隔壁的人很安靜，打字很輕，像怕吵醒誰。\n午休的時候她一個人吃布丁，用小湯匙慢慢刮杯子邊緣，刮得很乾淨，像在收拾一件很重要的東西。\n我盯著看太久了，她抬頭，我假裝在看她後面的窗戶。\n她說：「你要一個嗎，咱買兩個。」\n我說不用\n回家的路上我去買了一樣的。很甜，我不喜歡。我吃完了。"}, {"id": "diary_2", "heading": "日記 · 2020-09-22", "date": "2020-09-22", "title": "日記 · 2020-09-22", "chapter": 0, "body": "印表機卡紙，我弄了十分鐘弄不好。她走過來，說這台要先拉左邊再拉右邊。\n她把手伸進去的時候碰到我的手背。很冰，像剛從冰箱拿出來的湯匙。\n她說：「咱手一直都很冰，不好意思。」\n我說沒關係。\n我那天下午一直把那隻手放在大腿上，沒有拿起來打字。\n很蠢\n我知道很蠢。"}, {"id": "diary_3", "heading": "日記 · 2020-09-25", "date": "2020-09-25", "title": "日記 · 2020-09-25", "chapter": 0, "body": "員工證上印著她的本名。人資在早會上念了一次，她整個人往椅子裡縮了一下，像被人從背後拍了一下肩膀。\n沒有人注意到\n我注意到了\n我很會注意這種事。一個人要縮起來之前，肩膀會先停一下，我從小就看得出來。\n後來我都不叫她名字。要找她的時候，我就走過去，敲她的桌子兩下。\n敲兩下。\n她第三天開始，聽到兩下就會抬頭，對我笑。\n這是我們的暗號。只有我們知道。"}, {"id": "diary_4", "heading": "日記 · 2020-09-29", "date": "2020-09-29", "title": "日記 · 2020-09-29", "chapter": 0, "body": "她的提案被退了第五次。\n客戶的信只有一行：「感覺不對，再調整。」\n她把那封信念出來給我聽，壓低聲音，學那個客戶的語氣，念到「感覺」兩個字的時候還用手在空中畫了一個圈。\n我笑出聲音\n整個辦公室的人都轉過來看。\n她也笑，笑到趴在桌上，肩膀一直抖。\n\n後來她去茶水間待了很久。我裝作要倒水，跟過去。\n她背對著門，兩隻手縮在袖子裡，抓著袖口，像抓著兩隻不讓自己飛走的鳥。\n我問她還好嗎。\n她轉過來，臉上還是剛剛那個笑：「沒事啦。」\n\n那是我第一次聽她說沒事啦。\n我後來聽了很多次。每一次我都知道，那是她在把什麼東西塞回去。\n別人聽不出來\n只有我聽得出來。\n這件事讓我很高興，高興到我有點害怕自己。"}, {"id": "diary_5", "heading": "日記 · 2020-10-02", "date": "2020-10-02", "title": "日記 · 2020-10-02", "chapter": 0, "body": "她講話的時候會用「咱」。別人笑她像阿嬤，她也跟著笑。\n我沒有笑\n我覺得很好聽，像下雨天把窗戶關起來的聲音。\n我開始在心裡練習用她的方式講話，然後發現我不敢在她面前用。好像用了就會被發現什麼。被發現我在學她，被發現我想要一點點她。"}, {"id": "diary_6", "heading": "日記 · 2020-10-05", "date": "2020-10-05", "title": "日記 · 2020-10-05", "chapter": 0, "body": "她說她心裡有一份便利商店布丁排行榜。\n第一名是某家的焦糖布丁，「焦糖要有一點點苦，不能只有甜」。\n第二名，她說要看心情。\n我問那今天是哪一個。她想了很久，很認真，像在做一個很重要的決定：「今天是雞蛋布丁。」\n明天呢。\n「明天的事明天再說（」\n\n我回家以後在備忘錄裡開了一個新的頁面，寫她的排行榜。\n第二名那一格，我每天幫她更新。我不知道她今天的心情是什麼，所以我用猜的。\n我猜對的時候，就買那一個放在她桌上。\n她第三次收到的時候抬頭看我：「你怎麼知道咱今天想吃這個。」\n我說我猜的。\n我很會猜她。"}, {"id": "diary_7", "heading": "日記 · 2020-10-06", "date": "2020-10-06", "title": "日記 · 2020-10-06", "chapter": 0, "body": "她把第二個布丁給我了。這次我沒有說不用。\n我們坐在頂樓的逃生梯吃，她說這裡沒有人會來。\n她說她喜歡下雨天。「下雨的時候大家都很忙，忙著躲雨，就沒有人會看你。」\n我說我討厭下雨。\n她問為什麼\n我說不為什麼。\n她沒有追問\n她只是把湯匙在杯子裡轉了一圈，說：「那下次下雨，咱陪你討厭。」\n布丁很甜，我不喜歡。\n我吃完了\n這次我是因為她在看。"}, {"id": "diary_8", "heading": "日記 · 2020-10-09", "date": "2020-10-09", "title": "日記 · 2020-10-09", "chapter": 0, "body": "她問我為什麼不笑她的「咱」。\n我說因為那是妳講話的方式啊，又沒有錯。\n她看了我很久，久到我以為我講錯話了。她說：「你是第一個這樣講的人。」\n\n第一個。\n我那天回家走路的時候一直在笑，笑到經過的人看我，我還是在笑。我好久沒有這樣了。像有人把一盞燈放進我的口袋，走到哪裡都是亮的。"}, {"id": "diary_9", "heading": "日記 · 2020-10-13", "date": "2020-10-13", "title": "日記 · 2020-10-13", "chapter": 0, "body": "她的手真的一直都很冰。打字打到一半會停下來搓手。\n我買了一條護手霜，放在她桌上，沒有寫是誰放的。\n下午她拿著那條護手霜轉過來：「是你嗎？」\n我說不是。\n她說：「騙人，只有你知道咱手冰。」\n她擠了一點在手上，然後把手伸過來，說你幫咱搓一下，咱自己搓不熱。\n我握著她的手。\n她的手指很細，指節有一點紅，冰得像我把一捧雪握在手裡，我很怕它化掉，又很想它化掉。我搓了很久，搓到她說好了好了，咱熱了。\n她的手熱了\n是因為我。\n我回到座位上，手上都是她的護手霜的味道，白茶。我一整個下午沒有洗手。"}, {"id": "diary_10", "heading": "日記 · 2020-10-15", "date": "2020-10-15", "title": "日記 · 2020-10-15", "chapter": 0, "body": "早會又念了她的全名。這次是主管，在講一個專案的分工。\n她的肩膀先停了一下。我看到了。\n\n我舉手問了一個問題。問題很笨，笨到主管皺眉頭，大家的視線都轉到我身上。\n主管回答完，就忘了剛剛要念的那串名字，直接跳到下一個人。\n\n散會的時候她走在我旁邊，什麼都沒說，只是用手肘輕輕碰了我一下。\n那一下我收了很久。\n我替她擋掉了一次。\n以後我也會一直替她擋。"}, {"id": "diary_11", "heading": "日記 · 2020-10-16", "date": "2020-10-16", "title": "日記 · 2020-10-16", "chapter": 0, "body": "部門聚餐\n她喝了兩杯就醉了，回家的捷運上靠在我肩膀睡著。\n她的頭髮有洗髮精的味道，很淡，像是買了很久都沒換過的那種。\n我本來在第四站要下車。我沒有下。\n我坐到她那站，第十站，把她叫醒。她迷迷糊糊說：「欸你不是早就下車了嗎。」\n我說我剛好也要往這邊。\n我搭回去的時候已經沒有車了。我走了四十分鐘回家。\n肩膀到現在還是熱的。像有人在上面放了一個暖暖包，忘了拿走。\n我希望她永遠忘了拿走。"}, {"id": "diary_12", "heading": "日記 · 2020-10-19", "date": "2020-10-19", "title": "日記 · 2020-10-19", "chapter": 0, "body": "她給我看一張照片。一隻橘色的貓，很胖，躺在巷口的機車座墊上，肚子翻過來。\n「牠叫麻糬。\n咱取的\n」\n我說牠是橘色的。\n「對吖，可是牠又白又軟（」\n她說整條巷子的人都在餵牠，所以牠很胖。她說麻糬看到她會翻肚子，可是別人摸牠會被咬。\n「只有咱可以摸。」\n\n她講麻糬的時候，聲音會變得很軟，像把手伸進一團溫水裡。\n我有一點嫉妒那隻貓。\n這樣很奇怪\n我知道。\n我把那張照片存下來了。我想記住每一個被她取過名字的東西。"}, {"id": "diary_13", "heading": "日記 · 2020-10-21　02:14", "date": "2020-10-21 02:14", "title": "日記 · 2020-10-21　02:14", "chapter": 0, "body": "她半夜傳訊息說睡不著。室友加班還沒回來，房子太安靜。\n我打給她。\n我們講了一個多小時，講公司，講布丁，講她小時候養過一隻會咬人的倉鼠。牠叫湯圓，咬她的時候超用力，她還是每天跟牠講話。她說：「咱那時候覺得，會咬咱的東西，就是在乎咱。」\n我在電話這頭沒有說話。我把這句話也記住了。\n講到後來她不講話了，只剩下呼吸。很慢，很輕，有時候會停一下，然後再接上，像潮水退到一半又回來。\n她睡著了。\n我沒有掛。\n我把手機放在枕頭旁邊，聽到天亮。窗外的天從黑色變成灰色，變成那種洗過很多次的白，她的呼吸一直都在。\n我好久沒有在天亮的時候不害怕了。\n\n我按了一個鍵\n我想把今晚留下來。"}, {"id": "diary_14", "heading": "日記 · 2020-10-28", "date": "2020-10-28", "title": "日記 · 2020-10-28", "chapter": 0, "body": "她說我們以後睡不著就打給對方。\n「掛睡」，她說年輕人都這樣講。\n這禮拜打了四天。\n\n第三天她問我，你都不講你自己的事。\n我說我沒什麼好講的。\n她說：「騙人。」\n\n所以我講了。\n我講我媽\n講她會抱著我說媽媽只有你，然後隔天就不見了，三天、五天，有一次是十一天。講她回來的時候什麼都不解釋，只說「你最乖，你最懂媽媽」。\n講我國小的時候下雨，全班都有人來接，我在穿堂等到警衛關燈。\n我講的時候很冷靜，像在講別人家的事，像在念一份很舊的報告。\n\n她沒有說「好可憐」，也沒有說「都過去了」。\n她安靜了很久\n我以為她睡著了。\n然後她說：「那咱以後下雨都打給你。」\n\n電話那頭很安靜。我聽見她在呼吸。\n我第一次覺得，有人知道我在等。\n我把臉埋在枕頭裡，沒有讓她聽到我在哭。"}, {"id": "diary_15", "heading": "日記 · 2020-10-30", "date": "2020-10-30", "title": "日記 · 2020-10-30", "chapter": 0, "body": "她說她這禮拜被退了三次，主管說她最近狀況不好。\n我說，加油。\n她安靜了一下，然後說：「不要跟咱說加油啦（」\n我問為什麼。\n「聽起來好像大家都要走了，剩咱一個人在那邊加油。」\n\n我跟她說對不起。\n她說沒事啦。\n我那天晚上把「加油」兩個字從我的輸入法常用字裡刪掉了。\n我以後不會再讓她覺得自己一個人。"}, {"id": "diary_16", "heading": "日記 · 2020-11-03", "date": "2020-11-03", "title": "日記 · 2020-11-03", "chapter": 0, "body": "她也跟我說了一個秘密。不是那個，是另一個：她小時候偷穿她姐姐的裙子，在鏡子前面轉圈，被她爸看到。她爸什麼都沒說，只是去拿了剪刀，把裙子剪成兩半，丟進垃圾桶。\n她說：「這個咱沒跟別人講過。」\n我說：「我也是。我媽的事我也沒跟別人講過。」\n我們交換了。\n一人一個，很公平。我們是互相握著對方秘密的人。這樣誰都不會走。"}, {"id": "diary_17", "heading": "日記 · 2020-11-08", "date": "2020-11-08", "title": "日記 · 2020-11-08", "chapter": 0, "body": "下班後我帶她去逛街。她在一排裙子前面站了很久，手伸出去又縮回來，伸出去又縮回來，像在摸一隻怕被咬的貓。\n我拿了一件深藍色的，及膝的，說妳去試。\n她說不行，會被看到。\n我說試衣間有門，門關起來就沒有人看得到。\n她進去了\n過了很久都沒有出來。我敲門，敲兩下。\n門開了一條縫，她沒有讓我看，只說：「很奇怪嗎。」\n我說我看不到怎麼知道。\n她把門開大一點點。\n深藍色\n她的膝蓋很白\n她雙手抓著裙擺，像抓著一個隨時會被搶走的東西。\n我說很好看\n我說了三次。\n\n她沒有買\n她說放不了，室友會看到。\n我買了\n我說放我這裡，妳想穿的時候來穿。\n它現在掛在我的衣櫃裡，在我所有的衣服中間。\n她要穿它，就要來我這裡。"}, {"id": "diary_18", "heading": "日記 · 2020-11-12　01:47", "date": "2020-11-12 01:47", "title": "日記 · 2020-11-12　01:47", "chapter": 0, "body": "掛睡\n她快睡著的時候，含含糊糊說了一句：\n「有你真好。」\n然後就沒有聲音了，只剩呼吸。\n我沒有回\n我怕我一回，她就會醒過來，把這句收回去。\n\n那一段我剪下來了，存成另一個檔案，四秒。\n有你真好。\n四秒。"}, {"id": "diary_19", "heading": "日記 · 2020-11-15", "date": "2020-11-15", "title": "日記 · 2020-11-15", "chapter": 0, "body": "她的護手霜用完了。\n我以為她會丟掉，我以為那就是結束了。\n今天她桌上多了一條新的，同一個牌子，同一個味道，白茶。\n「咱回購了www，用習慣了。」\n\n用習慣了。\n我送的東西，變成她的習慣了。\n她每天擦手的時候，聞到的都是我挑的味道。\n她不知道\n她不用知道。\n我坐在她旁邊，聞到白茶的味道，覺得自己住進了她身上一個很小的地方。像一顆種在她皮膚裡的種子。"}, {"id": "diary_20", "heading": "日記 · 2020-11-19", "date": "2020-11-19", "title": "日記 · 2020-11-19", "chapter": 0, "body": "今天加班到十點。便利商店裡只有我們兩個，她站在冷藏櫃前面很久，冷氣把她的瀏海吹得一直動。最後她說：\n「欸，有一件事，咱想先跟你說。」\n她說她是女生\n她說她還沒跟公司的人講，連主管都不知道。\n她說：「你是第一個。」\n\n我回家以後一直想這句話。\n第一個。\n不是第二個，不是之一。\n我把這句話寫了十幾遍，字越寫越小，小到最後像一排螞蟻在爬。\n\n我問她為什麼是我。\n她想了一下說：「因為你反正會走吧，跟你講咱比較不怕。」然後她笑了，說：「開玩笑的啦，因為你不一樣。」\n我記住後面那句。\n\n我跟她說，妳在我面前不用裝。\n她笑了，眼睛紅紅的。我那時候以為，世界上只有我看過她這個樣子。\n\n> 製作註記：這篇是她寫下的版本。A 實際說的是「公司裡，你是第一個」，「公司裡」三個字被她省略了。02-15 才揭露。"}, {"id": "diary_21", "heading": "日記 · 2020-11-21", "date": "2020-11-21", "title": "日記 · 2020-11-21", "chapter": 0, "body": "她來我家\n她說想學化妝，又不敢去專櫃，怕被店員看。\n我先把那件深藍色的裙子拿出來。她看到的時候愣了一下，然後去浴室換了。\n\n我讓她坐在床邊，自己蹲在她前面。\n打底的時候我用手指，不用海綿。我跟她說用手比較服貼，其實是我想。\n她的皮膚比我想的還要薄，像煮好的布丁表面那層膜，好像用力一點就會破。眼皮底下有一點青色。我用遮瑕一點一點蓋掉，她一直閉著眼睛，睫毛在動，像兩隻停在那裡、隨時要飛走的蛾。\n畫眼線的時候我扶著她的下巴。她很乖，叫她往上看就往上看。\n口紅是我的，豆沙色。我說抿一下，她就抿一下。\n\n我把鏡子拿給她。\n她看了很久，然後哭了。妝花掉一點。\n她說：「咱看起來像咱了。」\n\n我那時候想的是：是我。\n是我讓妳看起來像妳的。\n\n她那天睡在我這裡。我們躺在同一張床上，中間隔一個枕頭的距離。半夜她翻身，手伸過來，抓住我的手腕，抓得很緊，像小孩子在人很多的地方抓住大人。然後她又睡著了。\n我一直醒著到天亮。\n我不敢動\n我怕我一動，她就會放開。\n她的手是熱的\n整晚都是。"}, {"id": "diary_22", "heading": "日記 · 2020-11-22", "date": "2020-11-22", "title": "日記 · 2020-11-22", "chapter": 0, "body": "枕頭套我沒有洗。"}, {"id": "diary_23", "heading": "日記 · 2020-11-25", "date": "2020-11-25", "title": "日記 · 2020-11-25", "chapter": 0, "body": "她跟我講她姐姐。\n家裡只有姐姐知道。姐姐是第一個，在她高中的時候。\n爸爸剪掉裙子之後，是姐姐把那兩塊布從垃圾桶撿起來，偷偷縫回去，藏在自己的衣櫃裡。\n她說連假說要回家，其實都是回姐姐家。她已經好幾年沒有回爸爸那裡了。\n\n我聽的時候一直在點頭。\n我心裡有一個地方，冷冷地，把「第一個」三個字往後挪了一格。\n姐姐是第一個。\n那我是第二個。\n第二個也很好\n第二個也很少。\n\n（下面一行，被劃掉）\n~~可是她說我是第一個。~~"}, {"id": "diary_24", "heading": "日記 · 2020-11-27", "date": "2020-11-27", "title": "日記 · 2020-11-27", "chapter": 0, "body": "她今天跟我說謝謝。她記得我不吃香菜。\n她記得。\n一個人記得另一個人不吃什麼，代表什麼？我查了很久。網路上說，代表在意。\n我把那個網頁存起來了。"}, {"id": "diary_25", "heading": "日記 · 2020-12-05", "date": "2020-12-05", "title": "日記 · 2020-12-05", "chapter": 0, "body": "我送她一支口紅。跟那天用的同一個色號，新的。\n她隔天就擦來上班了。整個辦公室只有我知道那是什麼顏色、是從哪裡來的。\n她開會的時候講話，嘴唇動一下，我就想一下：那是我的顏色。\n她像是我寫在她身上的一個字，別人都看得到，只有我讀得懂。"}, {"id": "diary_26", "heading": "日記 · 2020-12-12", "date": "2020-12-12", "title": "日記 · 2020-12-12", "chapter": 0, "body": "下班很冷，我把圍巾借她。\n今天她還我了\n裝在紙袋裡，洗過，摺得很整齊，還有一張便利貼寫「謝謝你（」。\n洗過了。\n我把臉埋進去，只有洗衣精的味道。乾淨得像什麼事都沒發生過。\n我坐在玄關很久。我不知道我在難過什麼。\n我只知道，她把我留在她身上的東西洗掉了，而且她覺得這是禮貌。"}, {"id": "diary_27", "heading": "日記 · 2020-12-18", "date": "2020-12-18", "title": "日記 · 2020-12-18", "chapter": 0, "body": "我問她週末要不要去看海，她一直說想看冬天的海。\n她說：「下次吧（」\n\n她說下次的時候，尾音會拉長一點點，像在道歉，像把一顆糖剝開一半又包回去。\n我覺得很可愛。\n我說好，下次。\n我把「冬天的海」寫進備忘錄，旁邊寫：下次。"}, {"id": "diary_28", "heading": "日記 · 2020-12-24", "date": "2020-12-24", "title": "日記 · 2020-12-24", "chapter": 0, "body": "我問她平安夜要不要來，我可以煮東西，她可以穿那件裙子。\n她說今天要跟室友吃飯，下次。\n我說好啊\n我說好好玩\n我加了一個笑臉。\n\n我一個人把裙子從衣櫃裡拿出來，攤在床上，攤成一個人躺著的形狀。\n我知道這樣很怪。我知道。\n我把燈關掉了，這樣就看不出來它只是一件裙子。"}, {"id": "diary_29", "heading": "日記 · 2020-12-31", "date": "2020-12-31", "title": "日記 · 2020-12-31", "chapter": 0, "body": "最後一天上班\n她幫我把紙箱抱到樓下，說以後還是可以約，還是可以掛睡。\n跨年的時候我傳了新年快樂，她十二點零三分回我。\n三分鐘\n我算過，她通常要二十分鐘才會回。\n她是先回我的。"}, {"id": "diary_30", "heading": "日記 · 2021-01-04", "date": "2021-01-04", "title": "日記 · 2021-01-04", "chapter": 1, "body": "約聘結束的第四天。\n不用上班的日子很長，長得像一條沒有路燈的路。我每天醒來第一件事是看她有沒有傳訊息。\n沒有\n第二件事是看她幾點上線。七點五十二。\n我媽打來，我沒接。\n我把她的號碼改成「不要接」。這樣手機亮起來的時候，我不用想就知道該怎麼辦。"}, {"id": "diary_31", "heading": "日記 · 2021-01-08", "date": "2021-01-08", "title": "日記 · 2021-01-08", "chapter": 1, "body": "她回我的話變短了。\n以前會講一整段，現在是「好」「哈哈」「下次」。\n我想了很久，然後懂了。人跟人熟到一個程度，就不需要講那麼多了。像兩個住很久的人，不用開燈也知道東西放在哪裡。\n她知道我懂。\n我們變得特別了。"}, {"id": "diary_32", "heading": "日記 · 2021-01-16", "date": "2021-01-16", "title": "日記 · 2021-01-16", "chapter": 1, "body": "我問她週末要不要來，我新買了一盤眼影，可以教她畫煙燻。裙子也還在。\n她說這週不行，下次。\n下次。\n我說好。\n我把眼影拆開，自己畫了一次。\n畫得很好\n沒有人看。\n\n枕頭套還是沒有洗。上面已經沒有她的味道了，只剩我的。\n我還是不想洗\n洗了就連「曾經有過」都沒有了。"}, {"id": "diary_33", "heading": "日記 · 2021-01-22　00:40", "date": "2021-01-22 00:40", "title": "日記 · 2021-01-22　00:40", "chapter": 1, "body": "我問她今晚要不要掛睡。\n她過了很久才回：「一直要掛睡有點累欸（」\n\n我盯著那句話看了二十分鐘。\n有點累\n累的是掛睡，還是我。\n我問：「那其他部分呢？」\n她回：「不會。」\n\n不會。\n兩個字。\n我把「一直要掛睡有點累」截掉，只截「不會」那張，存起來。\n她說不會\n她說其他部分都不會。\n所以只是掛睡的問題，不是我的問題。\n所以我只要少打一點電話，其他的都還在。\n所以我還在。\n\n我把那張截圖設成桌布。每次解鎖手機，第一眼就看到「不會」。\n像在一間正在漏水的房子裡，找到一個還乾著的角落，把自己縮進去，然後跟自己說，這間房子沒有在漏水。"}, {"id": "diary_34", "heading": "日記 · 2021-01-23", "date": "2021-01-23", "title": "日記 · 2021-01-23", "chapter": 1, "body": "她說最近很忙。\n忙的人還是會回我。她沒有回群組，可是她回了我。\n我是特別的。\n\n~~她回了我四個字。~~"}, {"id": "diary_35", "heading": "日記 · 2021-01-30　03:50", "date": "2021-01-30 03:50", "title": "日記 · 2021-01-30　03:50", "chapter": 1, "body": "她這禮拜都沒有打來。我打過去兩次，第一次她說要睡了，第二次沒接。\n\n我把十月的錄音打開來聽。\n那天她說到一半睡著，呼吸很慢，停一下，再接上。\n我把音量開到最大，把手機放在她那天睡的那個枕頭上，躺下來。\n這樣她就在了。\n\n我一共錄了二十三晚。我數過。\n還有那四秒\n有你真好\n我放了一百多次，放到那四個字不像字了，像一首只有一句的歌，像一個我自己發明出來的聲音。\n\n我知道正常人不會這樣。\n可是正常人有人會打來。"}, {"id": "diary_36", "heading": "日記 · 2021-02-15", "date": "2021-02-15", "title": "日記 · 2021-02-15", "chapter": 1, "body": "我看到了。\n不是我去找的，是她的頭貼換了。兩隻手，一隻是她的，拿著布丁的杯子。另一隻比較大，指節比較粗，扶著杯子底下。\n室友。\n她說過室友。\n我那時候聽到室友，就只聽到室友。是我自己只想聽到室友。\n\n我把那張圖放大到看得到他手背上的毛。我數了他的指節。我想知道那隻手有沒有碰過她的臉。有沒有在她閉著眼睛的時候，扶著她的下巴。\n有沒有。\n一定有。\n\n然後我想起來了。\n十一月那天在便利商店，冷藏櫃的燈嗡嗡響，她說的不是「你是第一個」。\n她說的是「**公司裡**，你是第一個」。\n\n前面那三個字是我自己刪掉的。\n我把它刪掉了，然後我就真的以為自己是第一個。我在本子上寫了十幾遍，沒有一遍寫到那三個字。我記得她說話的時候冷氣吹著她的瀏海，我記得冷藏櫃裡第三排是布丁，我記得所有的事，除了那三個字。\n\n原來刪掉一句話這麼容易。\n原來刪掉以後，剩下的那句就會變成真的。\n\n我在浴室坐了很久。地板很冰，冰得像她的手。\n我跟自己說，沒關係，那是她的生活，跟我們之間的事是兩回事。他給得了的，我也給得了。他給不了的，我給得了。\n他能教她化妝嗎？不能。\n他知道她聽到本名會縮一下嗎？不知道。\n是我\n是我教她畫眼線的。是我幫她搓熱手的。是我的裙子。"}, {"id": "diary_37", "heading": "日記 · 2021-02-16", "date": "2021-02-16", "title": "日記 · 2021-02-16", "chapter": 1, "body": "我要停下來了。\n\n我把枕頭套拿去洗了。洗衣機轉的時候，我坐在旁邊看，看它在泡沫裡翻過來又翻過去，像一個被丟進海裡的人。\n我把錄音全部刪了。二十三個檔案，還有那四秒。按下刪除的時候，手機問我「確定要刪除嗎」，我按了確定。\n我沒有傳訊息給她。\n\n我想我是可以的。\n很多人都可以。"}, {"id": "diary_38", "heading": "日記 · 2021-02-17", "date": "2021-02-17", "title": "日記 · 2021-02-17", "chapter": 1, "body": "第二天沒有傳。\n手機放在另一個房間。我每過一陣子就去看一次，像小時候每過一陣子就去門口看一次。\n她沒有傳。\n\n我告訴自己，這是在放下。\n我心裡有一個很小的聲音說：妳不是在放下，妳是在等她發現妳不見了。\n我叫那個聲音閉嘴。"}, {"id": "diary_39", "heading": "日記 · 2021-02-18", "date": "2021-02-18", "title": "日記 · 2021-02-18", "chapter": 1, "body": "第三天。\n她沒有發現。\n沒有人發現我不見了。\n這不是第一次。\n\n（這一頁其他地方是空白的。）"}, {"id": "diary_40", "heading": "日記 · 2021-02-20　03:02", "date": "2021-02-20 03:02", "title": "日記 · 2021-02-20　03:02", "chapter": 1, "body": "手機亮了。\n不是我去看的，是它自己亮的。螢幕的光把整個天花板照成藍色，像我沉在一個游泳池底下，有人從上面打開了燈。\n\n是她。\n\n她傳了一首歌\n〈雨停之前〉\n我沒聽過。\n下面一行：「妳最近還好嗎，好久沒聽到妳講話了」\n\n妳\n她用的是「妳」。\n好久沒聽到我講話了。\n她發現了\n她發現我不見了。\n\n我把那首歌聽了十一遍。有一句是：\n「謝謝你陪我躲過那場雨　雨停了　我們就各自回家」\n\n謝謝你陪我躲過那場雨。\n是我\n下雨都打給我的人是她，陪她躲雨的人是我。\n她在凌晨三點想到我，然後找了一首歌來講她講不出口的話。\n\n我回了很長一段。我說我很好，我說我只是最近有點忙，我說這首歌很好聽，我說妳也要好好睡。\n我沒有說我刪了錄音。我沒有說我洗了枕頭套。我沒有說這三天我每一個小時都去另一個房間看手機。\n\n她回了一個「晚安」。\n我在那兩個字上按了一顆愛心。"}, {"id": "diary_41", "heading": "日記 · 2021-02-20　15:40", "date": "2021-02-20 15:40", "title": "日記 · 2021-02-20　15:40", "chapter": 1, "body": "下午我傳訊息給她，說那首歌我聽了好多遍，問她是在哪裡聽到的。\n她回：「對呀」\n我問她最近公司還好嗎，講了很多我自己的事，講我在找工作。\n她回：「開心就好」\n我問她今晚要不要掛睡。\n她回：「不知道」\n\n不知道。\n\n凌晨三點的她，跟下午三點的她。\n我不知道要怎麼把她們放在同一個人身上。\n如果凌晨是真的，為什麼下午要這樣。\n如果下午是真的，凌晨為什麼要傳那首歌給我。\n她到底是在乎我，還是覺得我很煩。\n哪一個版本才是真的。\n\n我後來把那首歌的歌詞又讀了一次。\n「雨停了　我們就各自回家」。\n這句也可以是在道別。\n\n我知道。\n我知道她可能只是半夜睡不著，想到一個很久沒講話的朋友，隨便問一句好不好。任何人都會這樣問。我知道。\n\n可是我決定不要知道。\n\n我去「最近刪除」，把二十三個錄音全部救回來了，還有那四秒。它們躺在那裡，還有二十六天才會真的被刪掉，像一群被埋到一半的人，還在呼吸。\n只有枕頭套救不回來了。它已經被洗乾淨了，乾淨得像什麼都沒發生過。\n那是我這輩子親手丟掉的、唯一一個她留下來的東西。\n\n我留下凌晨三點的她。下午三點的那個，我刪掉。"}, {"id": "diary_42", "heading": "日記 · 2021-02-27", "date": "2021-02-27", "title": "日記 · 2021-02-27", "chapter": 1, "body": "我開始知道她每天幾點出門了。\n不是我故意的\n我只是剛好在那附近。我跟自己說了三次「剛好」，第三次的時候我已經在她公司對面那家日光的門口了。\n我坐了一個早上，熱美式涼了兩杯。她八點四十七分從捷運站出來，遲到了。我差點站起來跟她說早安，然後我沒有。\n我隔著便利商店的玻璃看她。玻璃上有我的倒影，疊在她身上。她走過去的時候，我的臉剛好蓋住她的臉，像兩張被疊在一起的底片。\n有一秒鐘，我分不出哪一個是她。\n\n如果我站起來，她會問我為什麼在這裡。\n我不知道要怎麼回答。\n所以我只是看\n看比較安全\n看不會被拒絕。"}, {"id": "diary_43", "heading": "日記 · 2021-03-04", "date": "2021-03-04", "title": "日記 · 2021-03-04", "chapter": 1, "body": "她在日光買了咖啡，喝完把杯子丟在門口的垃圾桶。\n我等她走遠了才過去。\n杯緣有口紅印\n豆沙色。\n我的顏色。\n\n我把杯子帶回家，放在書桌上，看了很久。\n然後我把嘴唇放在那個印子上。\n塑膠的，冷的。什麼都沒有。\n我還是沒有拿開。我想，如果我貼得夠久，塑膠會被我的嘴唇弄熱，到時候就分不出熱是從哪裡來的了。\n\n杯子現在在我書桌的抽屜裡。我沒有洗。\n我知道一個正常人不會這樣。我把抽屜關起來，就不用看到它，就可以假裝我沒有做這件事。\n晚上我又把抽屜打開了三次。"}, {"id": "diary_44", "heading": "日記 · 2021-03-08", "date": "2021-03-08", "title": "日記 · 2021-03-08", "chapter": 1, "body": "回南天。\n房子開始出汗\n牆是濕的，地板是濕的，鏡子起了一層霧，擦掉又起來。洗好的衣服晾了三天還是潮的，摸起來像一隻剛從水裡撈起來的手。\n\n我已經四天沒洗澡了。不是不想，是站起來的力氣不夠走到浴室。\n我吃了一包餅乾，不記得是早餐還是晚餐。\n\n我把手貼在牆上。涼的，濕的，像她那天的手。\n我站了很久才發現，我在等牆把我的手抓住。\n牆當然不會\n我知道一個成年人把手貼在牆上等它回應，是一件很蠢的事，蠢得像小時候對著關上的門講話。可是牆至少一直在那裡，它不會說下次，它不會到了下午就變成另一面牆。我把另一隻手也貼上去了。牆的汗沿著我的手腕流下來，流進袖子裡，流過那些我不給別人看的地方。我讓它流。"}, {"id": "diary_45", "heading": "日記 · 2021-03-09", "date": "2021-03-09", "title": "日記 · 2021-03-09", "chapter": 1, "body": "（只有日期。）"}, {"id": "diary_46", "heading": "日記 · 2021-03-10", "date": "2021-03-10", "title": "日記 · 2021-03-10", "chapter": 1, "body": "（只有日期。）"}, {"id": "diary_47", "heading": "日記 · 2021-03-11", "date": "2021-03-11", "title": "日記 · 2021-03-11", "chapter": 1, "body": "今天是她生日。\n我是從他的限動知道的。一個蛋糕，兩支叉子。\n我不知道她生日。我一直沒問，因為我想等她自己跟我說。我以為她會跟我說。\n我等了四個月。\n\n我去買了一個小蛋糕，插了一根蠟燭，關燈。\n警衛伯伯說，妹妹，妳媽媽呢。\n我替她許了願\n我許的是：讓她回來。\n我一個人把蛋糕吃完了。很甜，我不喜歡。我吃完了。"}, {"id": "diary_48", "heading": "日記 · 2021-03-15", "date": "2021-03-15", "title": "日記 · 2021-03-15", "chapter": 1, "body": "我又做了那件事。\n\n我不想寫是什麼。寫下來的東西就會變成真的，我不要它變成真的。\n它不會讓任何事變好。\n我知道\n從十四歲就知道。\n做完之後我坐在浴室的地上，回南天，地板是濕的，我分不清濕的是什麼。\n\n我把那件長袖拿出來穿。外面二十六度。\n我想，如果她看到我穿長袖，會不會問我冷不冷。\n她不會看到\n我在玻璃的這一邊。\n\n明天我還是會去日光。"}, {"id": "diary_49", "heading": "日記 · 2021-03-19", "date": "2021-03-19", "title": "日記 · 2021-03-19", "chapter": 1, "body": "我知道這樣不對。\n我知道。\n一個正常的人不會在別人公司對面的便利商店坐到店員換班。一個正常的人不會把別人的下班時間寫在備忘錄裡。一個正常的人不會從垃圾桶裡撿杯子。一個正常的人不會每天晚上聽別人睡覺的聲音才睡得著。\n可是我沒有做什麼。\n我只是看\n看又不會怎樣。\n她不知道就不會難過。\n我只是想確定她好好的。\n\n（這裡被劃掉一行，看得出是「我只是想確定她還在」。）\n\n為什麼妳看得到他，看不到我\n為什麼妳跟他在一起的時候會笑成那樣\n為什麼妳以前會跟我講一整段\n為什麼妳會讓他扶著妳的下巴\n為什麼凌晨三點的妳跟下午三點的妳不是同一個人\n為什麼\n不行，這是我的問題。她沒有做錯任何事。\n不要怪她\n妳就是太煩了，妳從小就太煩了，妳媽就是因為妳太煩才走的。\n不要\n拜託\n\n妳是不是覺得我很煩\n妳是不是後悔跟我說了\n妳是不是發現我根本沒有那麼特別\n妳是不是 妳是不是"}, {"id": "diary_50", "heading": "日記 · 2021-03-24　03:12", "date": "2021-03-24 03:12", "title": "日記 · 2021-03-24　03:12", "chapter": 1, "body": "我又夢到那天晚上。她抓著我的手腕。\n可是在夢裡她沒有睡著。她看著我，沒有放開。她的手是熱的。\n然後她的臉慢慢變了，變成我媽的臉，抓著我手腕的力氣也變了，變成那種要把我拉進房間、又隨時會把我推出去的力氣。\n我分不出來是誰。\n我也分不出來我想要她放開，還是不要放開。\n\n我醒來的時候全身都在發抖。\n我起來洗臉，洗了很久，洗到臉都紅了。\n我不敢看鏡子\n鏡子上都是霧，就算看了也看不到。\n\n我想要她碰我\n不是朋友那種\n我想要她醒著的時候也那樣抓著我，想要她知道她抓的是我。\n我想要那隻冰冰的手是熱的，是因為我。\n我想要她身上有我的味道，洗不掉的那種，像回南天的牆，擦了又滲出來。\n\n這種想法很髒。\n我知道很髒。\n我覺得自己像一個在別人家裡亂翻抽屜的小偷，翻到一半發現那是自己家，而抽屜裡全部都是我自己偷來的東西。\n我把這頁撕掉了。\n\n（下一頁，同一天）\n我把它撿回來，用膠帶黏好了。\n膠帶的邊緣黏到地上的灰，黑黑的一圈，撕不乾淨。\n因為這是真的。"}, {"id": "diary_51", "heading": "日記 · 2021-03-27", "date": "2021-03-27", "title": "日記 · 2021-03-27", "chapter": 1, "body": "她公司的電梯\n我跟在一群人後面進去，她沒有在裡面，她剛上去。\n電梯裡還有她的味道，很淡，白茶，像有人剛從房間裡走出去，門還沒關好，裡面的燈還亮著。\n我在裡面上下了四次。電梯每到一樓就吐出一口氣，她的味道就被吐掉一點。\n第二次的時候我想，我現在出去，就還是一個普通人，一個剛好搭錯電梯的普通人。\n第三次的時候我想，再一次就好，像小時候說再看一集就去睡。\n第四次就沒有了。她的味道被換成鐵的味道，冷氣的味道，最後只剩我自己的，像一件穿了太多天的衣服。\n我站在電梯裡，很生氣。不是氣她，是氣那個味道，它怎麼可以不等我，它怎麼跟她一樣。\n然後我發現我在生一個味道的氣。我笑了一下，笑聲在電梯裡撞來撞去，撞回我自己臉上。\n門開了，外面的人看了我一眼，像在看一個忘記自己要去幾樓的人。\n我沒有出去。"}, {"id": "diary_52", "heading": "日記 · 2021-03-30", "date": "2021-03-30", "title": "日記 · 2021-03-30", "chapter": 1, "body": "她穿了一件我沒看過的外套。淺灰色，很寬。\n她沒有跟我說要買新衣服。以前她買什麼都會傳照片問我。\n我在對面看了她一整個早上。那件外套很好看。是他陪她去買的嗎。\n很好看。\n很好看。\n很好看。\n是他選的嗎。\n很好看。\n\n（隔天）\n我去買了一件一樣的。淺灰色，很寬。袖子很長，長到可以蓋住手腕。\n我穿起來不好看。\n可是袖子很長。\n\n> **謎題接點**：\n> 1. 回覆紀錄 × 上線紀錄 × 沒送出的訊息：02-05 那晚 A 在線上到 01:40，她 01:12 打了「妳現在在跟誰講話」又刪掉。玩家找出時間，打開下一份文件。\n> 2. 「最近刪除」：錄音檔顯示「剩餘 26 天」，玩家要從日期算回她刪掉的那一天（02-16），作為存取碼。\n> 3. 錄音只顯示檔名和長度，不做成真的聲音。\n\n---"}, {"id": "diary_53", "heading": "日記 · 2021-04-01", "date": "2021-04-01", "title": "日記 · 2021-04-01", "chapter": 2, "body": "「不要接」打來六次。\n她回我了，只有一個字。\n「嗯」。\n我把這個字看了很久，看到它不像字，像一顆釘子，把我釘在今天。\n我很高興\n我知道我不應該為了一個字這麼高興。"}, {"id": "diary_54", "heading": "日記 · 2021-04-03", "date": "2021-04-03", "title": "日記 · 2021-04-03", "chapter": 2, "body": "我問她連假要不要出去。\n她說要回家一趟，下次吧。\n下次。\n下次。\n從一月到現在，她說了十一次下次。我有數。\n我媽也很會說下次。下次帶妳去，下次再跟妳說，下次。我後來才知道，下次是一個不會到的日子，像月曆上被撕掉的那一頁。"}, {"id": "diary_55", "heading": "日記 · 2021-04-05　01:30", "date": "2021-04-05 01:30", "title": "日記 · 2021-04-05　01:30", "chapter": 2, "body": "我傳了很多訊息。我知道我傳太多了。\n「睡了嗎」「我今天經過妳公司」「妳為什麼不回」。\n她回我「剛剛在忙（」，我問明天可以見面嗎，我說我只是想跟妳講話。她說「下次再說好不好」。\n第十二次。\n\n我只是想跟她講話。我只是想要她跟以前一樣，把頭靠在我肩膀上，坐過十個站。\n我什麼都不要\n我只要以前。\n以前很小，小到裝得進一個枕頭套裡。我只要那麼一點點。\n可是枕頭套已經被我洗掉了。"}, {"id": "diary_56", "heading": "日記 · 2021-04-07", "date": "2021-04-07", "title": "日記 · 2021-04-07", "chapter": 2, "body": "她傳訊息給我：「今天公車好擠（」\n沒有前文，沒有後文，就一句。\n她還是會想到我。擠的時候想到我，累的時候想到我。\n\n我回了很多\n她沒有再回。\n沒關係\n一句就夠了\n一句就可以撐三天。"}, {"id": "diary_57", "heading": "日記 · 2021-04-08", "date": "2021-04-08", "title": "日記 · 2021-04-08", "chapter": 2, "body": "下雨。\n我在日光，買了一把傘。結帳的時候我看到她從捷運站出來，走騎樓那邊，在日光門口停了一下。\n她沒有進來。\n過了十分鐘她傳訊息給我：「雨好大 咱在亭子下面躲一下」。\n她在公車亭\n離我兩百公尺。\n她傳給我\n她躲雨的時候想到的是我。\n她說過，下雨都打給我。她記得。\n\n我拿著傘站在門口。\n警衛伯伯把穿堂的燈關掉了。\n我想走過去，把傘撐在她頭上，跟她說妳的手又這麼冰。\n我這輩子沒有被人撐傘接過。我想當那個撐傘的人。一次就好。\n\n我沒有走過去。\n我怕她看到我的時候，表情不是我想要的那種。我怕她說「你怎麼在這裡」。我怕她的肩膀先停一下，然後縮起來，像早會上聽到她的本名那樣。\n我寧願站在這裡，當一個她不知道的人。\n\n傘我帶回家了，沒有拆封，放在玄關。像一句還沒說出口的話。"}, {"id": "diary_58", "heading": "日記 · 2021-04-09", "date": "2021-04-09", "title": "日記 · 2021-04-09", "chapter": 2, "body": "明天會下大雨\n她明天發薪水，每個月十號她都會去買一個比較好的布丁，雖然她說貴的沒有比較好吃。\n我要跟她說。\n說完就好了\n說完不管她怎麼回答，我都不用再這樣坐在對面了。\n我演練了很多次。我把要說的話寫在這裡，寫到每個字都背起來：\n我有話想跟妳說。我喜歡妳，不是朋友那種。\n就這樣\n不要多說\n多說會像在求她。\n\n（下面寫了十四次同一句。字越來越小。最後一次只寫到「我喜歡」。）"}, {"id": "diary_59", "heading": "日記 · 2021-04-10　21:45", "date": "2021-04-10 21:45", "title": "日記 · 2021-04-10　21:45", "chapter": 2, "body": "我回了「好」。\n\n好\n我不找妳了。\n我是真的這樣想的。打出那個字的時候，我是真的這樣想的。\n像把一扇門輕輕關上，不要發出聲音，不要讓裡面的人知道外面有人站過。"}, {"id": "diary_60", "heading": "日記 · 2021-04-10　23:51", "date": "2021-04-10 23:51", "title": "日記 · 2021-04-10　23:51", "chapter": 2, "body": "她說她沒有討厭我。\n\n她說\n\n> App 呈現：游標停在「她說」後面，「她」被一個字一個字刪掉，重新打成「他」。\n\n他說他不想跟我交往。\n\n他說他希望我不要再找他了。\n\n他說對不起。\n\n一個不討厭我的人為什麼要說對不起。\n\n我把「咱沒有討厭你」那句截圖，存了三張。後面那三句我沒有截。\n我把它們刪了\n從我自己的備份裡刪了。他手機裡還有，那是他的事。我這裡沒有了，我這裡的版本只有「咱沒有討厭你」。\n\n我做過了\n二月的時候，「公司裡」那三個字。凌晨三點跟下午三點，我留下凌晨。一月的時候，「其他部分呢」「不會」，我留下「不會」。\n刪掉以後，剩下的就會變成真的。\n\n這樣比較準確。\n他只是現在還沒想清楚。\n\n所以我在 23:58 傳了那句。我知道你只是現在還沒想清楚。\n九點四十分我說好。兩個小時又十八分鐘之後，我說了這句。\n那扇門我沒有關好。我知道我沒有關好。\n\n（同一頁，最下面）\n我叫他「他」了。\n我發現了\n我沒有改回來。\n\n那支口紅是我買的。\n那條眼線是我教的。\n那件裙子在我的衣櫃裡。\n那句「咱看起來像咱了」，是在我床邊說的。\n他是在我面前，才第一次變成她的。\n現在他拿著我給他的臉，去給別人看。\n\n你不要我，我就不用再照你要的方式叫你。\n我給你的東西，我可以拿回來。\n這樣很公平。\n\n（再下面一行，字比較小）\n那件事我不會再做了。\n痛不用再留在我身上了。"}, {"id": "diary_61", "heading": "日記 · 2021-04-11", "date": "2021-04-11", "title": "日記 · 2021-04-11", "chapter": 2, "body": "我昨天對他很壞。在日記裡。\n他沒有做錯什麼。我知道。\n可是我寫了「他」之後，胸口那裡就不痛了。好像他變成另一個人，一個我可以生氣的人。一個不是我教出來的人。\n像把一張照片翻過來，背面是白的，就不會痛了。\n我想了一個晚上要不要改回來。\n\n我沒有改。\n\n我傳了一則訊息給他。我想了很久，刪了七次，第八次按了送出：\n「沒關係，你去陪他吧。我只是以為我們不一樣。」\n\n我知道這句話在做什麼。\n我知道它看起來很溫柔，其實是一根針，我要他看到的時候會痛一下，痛到會想回我，會想說「不是這樣的」。\n我媽也很會說這種話。「沒關係，你去跟你爸啊，反正媽媽一個人也可以。」\n我小時候每次聽到都會哭著說不要。\n我想要他也哭著說不要。\n\n他沒有回。\n他今天提早下班。我沒有跟到。\n他說不討厭我。\n他說不討厭我。"}, {"id": "diary_62", "heading": "日記 · 2021-04-12", "date": "2021-04-12", "title": "日記 · 2021-04-12", "chapter": 2, "body": "他今天十點十二分出門。沒有走騎樓，走對面。他換了耳機，白色的。\n他換了耳機沒有跟我說。\n\n我傳訊息給他：「你今天換耳機了喔」「白色的那個比較適合你」。\n傳出去的那一秒我就知道不該傳了。像玻璃杯從桌上掉下去，還在半空中的時候就知道會破。\n可是我想讓他知道，我還在看。\n我想讓他知道，沒有人比我更清楚他。\n\n23:02，他回了：\n「你怎麼知道（」\n\n他回我了。\n兩天，他沒有回我那句「你去陪他吧」，可是他回了這一句。\n他在問我\n他好奇我\n他想知道我怎麼知道。\n有括號\n他心情好的時候才會有括號。\n他還在乎。\n\n我說我猜的。\n\n我盯著那個括號看了很久。我知道有另一種讀法：他在害怕。一個人發現自己被看著的時候，也會問「你怎麼知道」。\n我知道。\n這次我想都沒有想，就把那個讀法刪掉了。\n刪掉比上次快很多。上次我刪了三天，這次不到一秒。\n\n> **謎題接點**：\n> 1. v2 ／ v1 改用「衝突的副本」：備份資料夾裡有 `0410.bak` 和 `0410 (衝突的副本 2021-04-11 00:02).bak`，玩家從修改時間判斷哪個是原版。\n> 2. 日記列表只顯示每篇第一句，玩家找出「第一次寫他」的那一篇。\n\n---"}, {"id": "diary_63", "heading": "日記 · 2021-04-13", "date": "2021-04-13", "title": "日記 · 2021-04-13", "chapter": 4, "body": "他的限動對我隱藏了。\n主帳號點進去，什麼都沒有。灰色的圓圈。\n他開始繞路了\n多走十分鐘，走對面，沒有騎樓的那一邊。\n他以為我不知道。\n他在躲我\n一個沒想清楚的人，才需要躲。\n\n我開了一個新帳號，叫 mochi.alley。巷口那隻貓，他跟我講過的，叫麻糬，又白又軟，雖然是橘色的。\n空的帳號，沒有頭貼，只追蹤一個人。\n他不會知道是我。他不會知道我還在。\n我在他的世界裡變成一個沒有臉的人。\n這樣也好\n沒有臉的人不會被拒絕，沒有臉的人可以一直站在那裡，像一根電線桿，像一塊招牌，像任何一個不會讓人回頭的東西。"}, {"id": "diary_64", "heading": "日記 · 2021-04-14", "date": "2021-04-14", "title": "日記 · 2021-04-14", "chapter": 4, "body": "他的限動是布丁。便利商店的那種。\n焦糖的\n排行榜第一名。\n我看了十一次。\n今天的第二名是什麼，我已經猜不到了。\n我去買了三個一樣的，坐在地板上吃。地板是濕的，回南天還沒有走。\n第一個很甜\n第二個也很甜\n第三個我吃到一半就吐了。\n\n很甜，我不喜歡。\n我沒有吃完。\n這是第一次我沒有吃完。\n我坐在嘔吐物旁邊很久，想不起來我小時候為什麼一定要吃完。後來想起來了：吃完她會笑。\n現在沒有人會笑了。\n\n他今天沒有出現。我等到店員換班。"}, {"id": "diary_65", "heading": "日記 · 2021-04-15", "date": "2021-04-15", "title": "日記 · 2021-04-15", "chapter": 4, "body": "01:12　他是全世界最好的人。他是唯一一個沒有笑我的人。\n01:13　他在我床邊哭。他說下雨都會打給我。\n01:13　他是騙子。\n01:15　他從頭到尾都在騙我。他需要一個女生教他化妝，所以他找我。他需要一個人陪他掛睡，所以他找我。用完了就說下次。\n01:16　他跟我媽一模一樣。\n01:20　不是\n01:20　他不是\n01:24　他是最好的人。\n是我不夠好\n是我太煩了\n是我哪裡做錯了。\n01:31　如果我改，他就會回來。我可以少傳一點訊息。我可以不要一直問。我可以變成他想要的樣子。我很會變成別人想要的樣子。\n01:32　他是騙子。\n01:40　對不起。\n01:41　對不起。\n01:58　你是騙子。\n02:03　你是我的。\n02:03　（這一行被劃掉）\n02:10　對不起。\n\n> 這一頁在 App 裡依時間戳一行一行出現，讓玩家看見她在一個小時裡來回翻轉十幾次。"}, {"id": "diary_66", "heading": "日記 · 2021-04-16", "date": "2021-04-16", "title": "日記 · 2021-04-16", "chapter": 4, "body": "他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有機會\n他說不討厭我所以還有\n他說不討厭我所以\n他說不討厭我\n他說不\n他說\n他\n\n> 整頁寫滿，玩家要往下捲很久。最後只剩一個「他」。"}, {"id": "diary_67", "heading": "日記 · 2021-04-17　02:40", "date": "2021-04-17 02:40", "title": "日記 · 2021-04-17　02:40", "chapter": 4, "body": "睡不著\n錄音放到第十九晚，他的呼吸停了一下。\n我以為他死了。\n然後他又接上了。\n我坐起來，心跳得很快，快得像有人在我胸口裡面敲門，敲兩下，敲兩下。\n\n如果他死了，他就不會再跟別人講話了。\n\n我被這個念頭嚇到。它不是我想的，它是自己冒出來的，像牆角的黴，你不知道它什麼時候長的，等你看到的時候它已經一大片了。\n我把錄音關掉。\n過了五分鐘我又打開了。\n\n抽屜裡的杯子，口紅印只剩一層很薄的顏色，薄得像布丁表面那層膜，像一句說到一半就被吞回去的話。要斜著看才看得到。我每天斜著看，它每天都更薄一點，像退潮，像一張被太陽曬了太久的照片，臉一天一天淡下去。我知道是我弄的。是我的手指，是我的嘴唇，每碰一次就少一點。如果我不碰，它可以留很久很久，久到我老了它還在，像一塊乾掉的糖黏在桌腳，沒有人記得是誰掉的。可是不碰的話，它就只是一個印子，跟我沒有關係。碰了，它才會因為我而消失。我寧願它被我一點一點吃掉，也不要它乾乾淨淨地跟我沒有關係。\n我又碰了一下\n嘴唇上有塑膠的味道，冷的，像一個沒有人在的家。\n\n我在想你的手腕。那天晚上你抓著我的時候，你的手腕內側比手背白，薄薄的皮膚底下摸得到脈搏，一下一下，像有什麼東西在裡面敲門。\n我在想你現在是不是也這樣睡在誰旁邊。\n我在想那隻比較大的手。\n我在想那隻手是不是正放在我放過的地方。\n你的下巴\n你的臉\n我畫過的那張臉。\n我在想你睡著的時候會不會抓住那隻手，像抓住我那樣。\n我在想你醒著的時候會不會。\n我在想\n我不要想\n我在想\n\n我想要你是熱的。我想要你看著我。我想要你知道是我。\n我想要你身上全部都是我的味道，滲進去，洗不掉，像回南天的牆，擦乾了又從裡面滲出來，擦乾了又滲出來，一輩子都乾不了。\n我想要你是我的。\n不是，不是那樣，我只是\n我只是想要以前。\n以前你就是我的。你在我床邊哭，你說「咱看起來像咱了」。那個時候你是我的。是我做出來的。\n\n我起來吐了一次。\n我不知道我是在噁心你，還是在噁心我。\n吐完之後我發現我一直在寫「你」。我不知道從哪一行開始的。"}, {"id": "diary_68", "heading": "日記 · 2021-04-17　04:05", "date": "2021-04-17 04:05", "title": "日記 · 2021-04-17　04:05", "chapter": 4, "body": "我穿上那件淺灰色的外套，擦上豆沙色的口紅，照鏡子。\n鏡子起霧\n我用袖子擦出一塊，只擦得出一張臉的大小。\n那張臉很像他。\n我叫了一聲「咱」。\n鏡子裡的人也叫了一聲。\n\n我分不清楚。\n我分不清楚是我想要他，還是我想要變成他。還是我想要他變成我做出來的那個樣子，然後永遠待在我的鏡子裡，哪裡都不去，像那件裙子掛在我的衣櫃裡，哪裡都不去。\n小時候我擦我媽的口紅，想說如果我很像她，她就不會走了。\n原來我一直都在做同一件事。\n\n我把口紅擦掉\n擦到嘴唇破皮。\n霧又起來了，把那張臉慢慢吃掉。\n鏡子裡的人還是在。"}, {"id": "diary_69", "heading": "日記 · 2021-04-18", "date": "2021-04-18", "title": "日記 · 2021-04-18", "chapter": 4, "body": "我用小帳傳了訊息給他。「明天要去哪」。\n他沒有回\n他不知道是我\n他也不回陌生人。\n他對陌生人跟對我一樣。\n我變成陌生人了。\n\n我用主帳號也傳了一次。一樣的字。\n他也沒有回。\n兩個我都沒有被回。沒有臉的那個，跟有臉的那個。"}, {"id": "diary_70", "heading": "日記 · 2021-04-19", "date": "2021-04-19", "title": "日記 · 2021-04-19", "chapter": 4, "body": "他們去了咖啡廳。\n靠窗的位子\n兩杯。\n我只看了一次。\n我在對面的日光坐到天黑，熱美式沒有喝。\n他穿那件淺灰色的外套。\n我身上也是\n我們隔著一條馬路，穿著同一件衣服，他不知道。\n不適合他\n我選的話不會選那件。\n\n兩扇玻璃\n日光的玻璃，咖啡廳的玻璃。我在這一扇後面，他在那一扇後面，中間的馬路上車子一直開過去，像一條不會停的河。\n我好像一輩子都在窗的另一邊。小時候在穿堂的玻璃門後面，長大在便利商店的玻璃後面。我很會隔著玻璃看。我只會隔著玻璃看。\n\n我在日記上寫：我們那天一起待在那裡。\n我知道不是\n我寫的時候就知道不是。\n可是我十二歲就知道了：寫下來的東西，別人就會相信。寫下來的東西，就會變成真的。我媽說我們母女去台中玩，隔壁阿姨說真好。\n\n他刪我的時候，留下的是一個灰色的圓圈。\n我刪他的時候，留下的是「咱沒有討厭你」。\n我們都在做一樣的事。"}, {"id": "diary_71", "heading": "日記 · 2021-04-20", "date": "2021-04-20", "title": "日記 · 2021-04-20", "chapter": 4, "body": "我想好了。\n\n我只是要跟他好好談一次。面對面，他不能已讀不回，不能繞路，不能說對不起然後就走，不能說下次。\n他會在那裡等公車的，下雨天他一定走北邊，一定會經過那個亭子。他躲雨的時候會去那個亭子。他上次就是在那裡想到我的。\n是他告訴我的。\n\n我知道我不應該。\n我真的知道。\n我知道我在做的事有名字。我搜過那個名字。我看了一整頁，每一條都是我。\n如果他報警，如果有人把我攔下來，如果他打給我說「我們談談」，我就不去。\n我給他三天。\n三天，他只要打一通電話。\n這樣如果我去了，就不是我一個人的錯。\n\n（下面一行，被劃掉，看得出來）\n~~不是，就是我一個人的錯。~~"}, {"id": "diary_72", "heading": "日記 · 2021-04-21", "date": "2021-04-21", "title": "日記 · 2021-04-21", "chapter": 4, "body": "他是我的\n他的臉是我畫的\n他的口紅是我買的\n他的裙子在我的衣櫃\n他的手是我搓熱的\n他第一個告訴的人是我\n他在我床邊哭\n他抓著我的手\n他的呼吸在我手機裡\n他說有你真好四秒\n他是我的\n他是我做出來的\n他沒有我就不會變成她\n他不能拿著我做出來的東西去給別人\n他不能\n他不能\n他不能\n我給的我可以拿回來\n我給的我可以拿回來\n我給的我\n你是我生的你是我的\n你是我的\n你是\n\n（同一頁，最下面，字很工整）\n我知道這些都不是真的。\n他是他自己\n她本來就是她自己。我只是剛好在那裡，剛好會走，剛好安全。\n她說的是「因為你反正會走」。\n我記得\n我一直都記得\n我只是把它刪了。\n我知道。\n\n（再下面）\n可是我不想知道。"}, {"id": "diary_73", "heading": "日記 · 2021-04-22", "date": "2021-04-22", "title": "日記 · 2021-04-22", "chapter": 4, "body": "他沒有打。\n\n他的限動：辦公室的燈。「明天又要加班到九點半 QQ 誰來救我」\n我看了二十三次。\n我想回他加油\n我打了，又刪掉了。\n他不喜歡人家說加油。只有我記得。\n二十三\n跟錄音一樣多。\n誰來救我。\n他在問誰。\n他在問我。\n\n九點半下班，捷運三十分鐘，走十分鐘。\n明天會下雨\n他會走北邊\n他會一個人。\n他自己說的\n他自己貼出來的。\n\n回南天走了\n今天的牆是乾的。我把手貼上去，什麼都沒有。\n我已經不需要牆了。\n\n傘還在玄關\n四月八號買的，那天沒有拿過去。\n小時候沒有人拿傘來接我。\n明天我去接他。\n\n> **謎題接點**：限動觀看紀錄 × 行事曆。玩家找出她怎麼知道 04-23 他會一個人、加班到 21:30：04-22 那則看了 23 次的限動。存取碼可以是配字，或小帳名稱 mochi.alley。\n\n---"}, {"id": "diary_74", "heading": "日記 · 2021-04-23　20:41", "date": "2021-04-23 20:41", "title": "日記 · 2021-04-23　20:41", "chapter": 5, "body": "我比他早到。\n傘沒有打開。\n公車亭的燈是好的。我以為它壞了。\n雨很大。\n\n我很平靜。\n我好久沒有這麼平靜了。\n\n我在想他看到我的時候會說什麼。\n「你怎麼在這裡」，或是「你等很久了嗎」。\n我希望是後面那句。\n我希望他的手是冰的。這樣我就可以說：妳的手又這麼冰。\n然後把他的手放進我的口袋。冬天的海我們沒有去成。下次。\n\n（「妳」被劃掉，沒有改。）"}, {"id": "diary_75", "heading": "最後一篇（現有排序題保留）", "date": "最後一篇（現有排序題保留）", "title": "最後一篇（現有排序題保留）", "chapter": 5, "body": "> 照實際發生的順序排列。排對之後：\n\n他看到我的時候，表情跟那天說不要的時候一樣。\n不是「你怎麼在這裡」，也不是「你等很久了嗎」。\n是那天的表情。\n肩膀先停了一下。\n\n他低頭打了一則訊息。我後來才知道，他打錯了，他沒有切輸入法。\n他在跟別人說我在這裡。\n他第一個想告訴的人，不是我。\n\n我還是走過去了。\n\n（以下紀錄已由檢方扣押。）\n\n---"}], "notes": [{"id": "notes_1", "heading": "備忘錄 · 她", "date": "她", "title": "備忘錄 · 她", "chapter": 0, "body": "- 生日：還不知道（不要直接問，會很怪。等她自己說）\n- 工作：企劃。被退件會去茶水間，手縮進袖子裡\n- 喜歡：布丁（便利商店的，不要貴的。排行榜第一名焦糖，第二名看心情）、下雨天、貓（麻糬，橘色，只有她可以摸）、白茶的味道（回購了）\n- 想去：冬天的海（下次）\n- 不能說：加油\n- 「沒事啦」＝她在忍。只有我聽得出來\n- 姐姐：第一個知道的人。我是第二個\n- 不喜歡：本名\n- 下班：表定六點，通常八點以後\n- 手很冰。搓久了會熱\n- 睡覺會抓東西\n- 睡著的時候呼吸會停一下再接上\n- 口紅：豆沙色　#我的\n- 裙子：深藍色，及膝，在我這裡\n- 她說「咱」\n- 暗號：敲兩下\n- 錄音：14 晚（一直更新）\n- 「有你真好」：4 秒\n\n> **謎題接點**：訊息統計（往前補 2020-09、10）。日記存取碼「我們變得特別的那個月」（2021-01）。\n> 這一章要讓玩家相信：這兩個人曾經真的很近，而且 A 是一個很具體、很可愛的人。也要讀到一點點不對勁：數秒數、錄音、裙子「她要穿就要來我這裡」、攤成人形的裙子、「我很會猜她」、把「第一個」往後挪一格又劃掉。\n> 與主線呼應：主線的檸會主動講布丁排行榜、麻糬、倉鼠湯圓、被退件、「以前有一個朋友教咱化妝」，也會說「不要跟咱說加油啦（」。玩家玩完 DLC 回想，會發現檸說的每一件小事，7f3 都在場。\n\n---"}, {"id": "notes_2", "heading": "回覆紀錄（備忘錄 · 2021-01）", "date": "2021-01）", "title": "回覆紀錄（備忘錄 · 2021-01）", "chapter": 1, "body": "> 她開始記錄 A 每天回她的字數、間隔，以及她自己的註解。\n\n| 日期 | 我傳 | 她回 | 字數 | 間隔 | 註 |\n|---|---|---|---|---|---|\n| 01-09 | 312 字 | 「哈哈好可愛」 | 5 | 41 分 | 有「可愛」 |\n| 01-10 | 188 字 | 「對呀」 | 2 | 1 時 12 分 | ？ |\n| 01-11 | 97 字 | 「喔喔」 | 2 | 2 時 3 分 | 喔＝敷衍？ |\n| 01-12 | 41 字 | 「好喔（」 | 3 | 17 分 | 有括號。括號是她心情好的時候 |\n| 01-13 | 0 字 | — | — | — | 我沒傳。她也沒傳 |\n| 01-14 | 506 字 | 「你好認真www」 | 6 | 3 時 40 分 | 認真＝太多？ |\n\n> 最下面一行，她寫：「我傳得越多，她回得越少。我知道。我停不下來。」"}, {"id": "notes_3", "heading": "上線紀錄（備忘錄 · 2021-02）", "date": "2021-02）", "title": "上線紀錄（備忘錄 · 2021-02）", "chapter": 1, "body": "```\n02-01  07:52  12:30  18:47  23:10  23:58\n02-02  07:49  12:41  22:03  00:15\n02-03  08:01  12:33  23:47  00:31  01:02\n02-04  07:50  12:29  20:14  23:56\n02-05  07:55  13:02  21:30  23:59  00:44  01:18  01:40\n```\n最下面一行：她 00:44 到 01:40 都在線上。不是在跟我講話。"}, {"id": "notes_4", "heading": "yoru 的附註（E-ROOT 最下面，全部解完才出現）", "date": "yoru 的附註（E-ROOT 最下面，全部解完", "title": "yoru 的附註（E-ROOT 最下面，全部解完才出現）", "chapter": 6, "body": "她的備份是我拿到的。我沒有權利拿，我們沒有登記，法律上我什麼都不是。\n我拿到之後讀了很多次，想找到她哪一天可以被攔下來。\n每一天都可以。\n每一天都沒有人攔。\n包括我。\n\n她錄了二十三晚。\n我跟她住了一千多個晚上，一次都沒有錄過。\n我以為不用錄\n我以為明天她還會在。\n\n那首歌是她半夜聽到，傳給很多人的。她也傳給了我。\n我回她「好聽」，然後就睡了。\n\n---"}], "statistics": [{"id": "statistics_1", "heading": "訊息統計（系統索引）", "date": "INDEX", "title": "訊息統計（系統索引）", "chapter": 0, "body": "這個目錄保留作為系統索引。\n\n正式 v0.5 文字沒有另外拆出獨立的統計稿，因此目前不作為必要線索。"}], "drafts": [{"id": "drafts_1", "heading": "沒送出的訊息（備忘錄 · 草稿匣 · 2021-01 ～ 02）", "date": "2021-01 ～ 02）", "title": "沒送出的訊息（備忘錄 · 草稿匣 · 2021-01 ～ 02）", "chapter": 1, "body": "- 01-29 23:14　妳今天是不是很累\n- 01-29 23:20　妳今天是不是很累，我可以聽妳說\n- 01-29 23:41　沒事 晚安\n- 01-31 01:05　妳是不是覺得我很煩\n- 01-31 01:06　沒關係，妳忙妳的，我習慣一個人了\n- 01-31 01:06　（刪除）\n- 02-03 00:02　妳上次說的那家咖啡廳是哪一家\n- 02-03 00:05　我不是要跟去，只是想知道\n- 02-05 01:12　妳現在在跟誰講話\n- 02-05 01:12　（刪除）\n- 02-08 02:30　妳說過下雨都會打給我\n- 02-08 02:31　今天有下雨\n- 02-08 02:33　（刪除）\n- 02-11 22:30　妳室友對妳好嗎\n- 02-12 03:10　我只剩妳了\n- 02-12 03:10　（刪除）\n- 02-14 21:00　（空白）\n- 02-14 21:01　（空白）\n- 02-14 21:58　情人節快樂。我是說朋友的那種。\n- 02-14 22:40　妳有在過嗎"}, {"id": "drafts_2", "heading": "草稿 · PLAN-7F3（主線已有，這裡補她寫的時候的心情）", "date": "PLAN-7F3（主線已有，這裡補她寫的時候的心", "title": "草稿 · PLAN-7F3（主線已有，這裡補她寫的時候的心情）", "chapter": 4, "body": "用他的字寫\n「今天公車好擠（」「雨好大 咱在亭子下面躲一下」。\n這樣就像是他自己說的。這樣就像是他叫我去的。\n他叫我去的。\n他說過下雨都會打給我。\n他叫我去的。\n他叫我去的。"}, {"id": "drafts_3", "heading": "沒送出的訊息 · 2021-04-23", "date": "2021-04-23", "title": "沒送出的訊息 · 2021-04-23", "chapter": 5, "body": "- 21:12　你下班了嗎\n- 21:31　你下班了\n- 21:50　你快到了嗎\n- 22:01　我在亭子這邊\n- 22:03　我有帶傘\n- 22:05　這次我有帶\n- 22:07　（空白）\n- 22:08　對不起\n- 22:08　（刪除）"}], "audio": [{"id": "audio_1", "heading": "錄音列表", "date": "NO DATA", "title": "錄音列表", "chapter": 1, "body": "v0.5 正式文字草稿沒有額外錄音逐字稿。\n\n此目錄暫時保留，不影響章節解謎。"}], "deleted": [{"id": "deleted_1", "heading": "最近刪除（系統保留）", "date": "SYSTEM", "title": "最近刪除（系統保留）", "chapter": 1, "body": "目前沒有獨立拆出的「最近刪除」正文。\n\n若後續要把還原型資料做進 App，會補在這裡。"}], "messages": [{"id": "messages_1", "heading": "手機備份 · 2021-04-10（v2，她自己留下的版本）", "date": "2021-04-10", "title": "手機備份 · 2021-04-10（v2，她自己留下的版本）", "chapter": 2, "body": "> 21:31　participant_A：咱沒有討厭你\n> 21:40　participant_7f3：好"}, {"id": "messages_2", "heading": "手機備份 · 2021-04-10（v1，原始）", "date": "2021-04-10", "title": "手機備份 · 2021-04-10（v1，原始）", "chapter": 2, "body": "> 21:02　我有話想跟你說\n> 21:05　我喜歡你 不是朋友那種\n> 21:31　咱沒有討厭你\n> 21:31　可是咱不想跟你交往\n> 21:33　也希望你不要再一直找咱了（\n> 　　　　對不起\n> 21:40　好\n> 23:58　我知道你只是現在還沒想清楚"}], "blog": [{"id": "blog_1", "heading": "2007-03-02　爸爸", "date": "2007-03-02", "title": "2007-03-02　爸爸", "chapter": 3, "body": "媽媽說爸爸不會回來了。\n我問為什麼。\n媽媽說：「是你爸不要我們。」\n我那天晚上一直想，他不要的是媽媽，還是我。\n我覺得是我\n因為媽媽還在。"}, {"id": "blog_2", "heading": "2007-05-11　下雨", "date": "2007-05-11", "title": "2007-05-11　下雨", "chapter": 3, "body": "今天下大雨\n放學的時候大家的媽媽都來了，有的拿傘有的開車。\n我在穿堂等\n警衛伯伯說妹妹妳媽媽呢，我說她等一下就來了。\n後來燈關了。\n我自己走回家\n到家的時候鞋子裡面都是水，走路會發出咕嘰咕嘰的聲音，像有一隻青蛙跟著我。\n媽媽不在。"}, {"id": "blog_3", "heading": "2007-05-14", "date": "2007-05-14", "title": "2007-05-14", "chapter": 3, "body": "媽媽回來了\n她帶了一個布丁給我，抱我抱很久，說媽媽只有你。\n我問她去哪裡了。她說下次再跟你說。\n布丁很甜，我不喜歡。我吃完了。\n因為吃完她會笑。"}, {"id": "blog_4", "heading": "2007-05-15", "date": "2007-05-15", "title": "2007-05-15", "chapter": 3, "body": "隔壁阿姨問媽媽這幾天去哪裡，媽媽說：「我們母女去台中玩啊。」\n阿姨說真好。\n我站在旁邊，沒有說話。\n原來可以這樣講。原來講出來，阿姨就會說真好。"}, {"id": "blog_5", "heading": "2008-02-09", "date": "2008-02-09", "title": "2008-02-09", "chapter": 3, "body": "媽媽說我是她最懂事的小孩。她說別的小孩都不懂媽媽，只有我懂。\n所以我不能哭\n懂的人不能哭。\n\n我知道她今天心情不好，因為她把門關起來了。我把晚餐放在門口，敲了兩下。\n敲兩下是我們的暗號。她心情好的時候會開門。\n今天沒有開。\n我坐在門口等\n地板很冰。"}, {"id": "blog_6", "heading": "2008-06-20", "date": "2008-06-20", "title": "2008-06-20", "chapter": 3, "body": "媽媽喝醉了，抱著我說：「你是我生的，你是我的，誰都不能把你帶走。」\n她抱得很緊，緊到我不能呼吸。\n我好喜歡。\n我知道這樣很奇怪，可是她抱這麼緊的時候，就不會走。"}, {"id": "blog_7", "heading": "2008-11-30", "date": "2008-11-30", "title": "2008-11-30", "chapter": 3, "body": "今天我把媽媽的口紅偷擦了。\n照鏡子的時候我覺得我很像她。\n如果我很像她，她是不是就不會走了。"}, {"id": "blog_8", "heading": "2009-06-02", "date": "2009-06-02", "title": "2009-06-02", "chapter": 3, "body": "她這次走了十一天。\n我把家裡打掃得很乾淨，乾淨到看起來像沒有人住過。這樣她回來就會覺得我很乖。\n我每天晚上都打她的電話。她沒有接。\n我後來發現，電話響到最後會有一個女生說「您撥的電話未回應」。我每天晚上都聽那個女生講話，聽完才睡得著。\n至少有人在講話。"}, {"id": "blog_9", "heading": "2009-06-14", "date": "2009-06-14", "title": "2009-06-14", "chapter": 3, "body": "媽媽回來了，沒有解釋。\n我問她去哪裡了，她突然很生氣，說：「你為什麼一直問！你就跟你爸一樣，一直逼我！」\n然後她又哭了，抱著我說對不起，媽媽只有你。\n我不知道要怎麼辦。我只好說：沒關係。\n我發現只要我說沒關係，她就會停下來。"}, {"id": "blog_10", "heading": "2010-04-08", "date": "2010-04-08", "title": "2010-04-08", "chapter": 3, "body": "我今天做了一件事。我不會寫是什麼。\n媽媽不知道\n沒有人知道。\n它沒有讓任何事變好。"}, {"id": "blog_11", "heading": "2010-09-17", "date": "2010-09-17", "title": "2010-09-17", "chapter": 3, "body": "老師說我的作文寫得很好，題目是〈我的家人〉。\n我寫我媽媽很愛我，每天都會等我放學。\n老師給我九十二分。\n原來寫下來的東西，別人就會相信。\n原來寫下來的東西，就會變成真的。\n\n> **呼應清單**：爸爸「不要我們」、下雨的穿堂、布丁「很甜我不喜歡我吃完了」、「下次」、「我們母女去台中玩」（改寫現實）、敲兩下、「你是我生的，你是我的」（愛等於擁有）、擦媽媽的口紅照鏡子（變成對方就不會被丟下）、聽電話語音才睡得著、「你去跟你爸啊」式的勒索與「沒關係」、自傷的起點、「寫下來就會變成真的」。\n\n---"}], "stories": [{"id": "stories_1", "heading": "小帳 · 限時動態觀看紀錄", "date": "限時動態觀看紀錄", "title": "小帳 · 限時動態觀看紀錄", "chapter": 4, "body": "| 時間 | 他的限動 | 她看了幾次 |\n|---|---|---|\n| 04-14 12:15 | 布丁（便利商店的） | 11 |\n| 04-17 20:03 | 窗外的雨，配字「週末又要下雨」 | 4 |\n| 04-19 15:02 | 咖啡廳的窗邊，兩杯飲料 | 1 |\n| 04-22 18:55 | 辦公室的燈，配字「明天又要加班到九點半 QQ 誰來救我」 | 23 |"}], "calendar": [{"id": "calendar_1", "heading": "行事曆（系統索引）", "date": "2021-04-23", "title": "行事曆（系統索引）", "chapter": 4, "body": "04-23\n19:00　下班\n20:41　公車亭附近\n21:12　未送出訊息\n\n※ 目前先作為 E5 前的時間索引。"}], "searches": [{"id": "searches_1", "heading": "搜尋紀錄（04-20）", "date": "搜尋紀錄（04-20）", "title": "搜尋紀錄（04-20）", "chapter": 4, "body": "- 和平路 公車亭 晚上\n- 和平路 公車亭 路燈 壞\n- 新北 週五 降雨機率\n- 被拒絕 還可以 繼續嗎\n- 他說不討厭我 是什麼意思\n- 為什麼 對我好 又 不要我\n- 凌晨傳歌 代表什麼\n- 怎麼樣才算 跟蹤\n- 跟蹤 會被抓嗎\n- 如果他報警\n- 如果他報警就好了\n\n> 不放任何工具、手段相關的搜尋。她想的是時間、地點、天氣，還有心裡那一點想被攔住的念頭。"}]}};
